let outer = document.querySelector(".outer");
let inner = document.querySelector(".inner");

outer.addEventListener("click", () => {
  console.log("Outer clicked");
});

inner.addEventListener("click", () => {
  console.log("Inner clicked");
});

// Click on .inner:
// → "Inner clicked"
// → "Outer clicked" (event bubbles up!)

let outer = document.querySelector(".outer");
let inner = document.querySelector(".inner");

// Third argument = true → capturing phase
outer.addEventListener("click", () => {
  console.log("Outer captured");
}, true);

inner.addEventListener("click", () => {
  console.log("Inner clicked");
});

// Click on .inner:
// → "Outer captured" (capturing goes down first)
// → "Inner clicked" (target reached)

let outer = document.querySelector(".outer");
let inner = document.querySelector(".inner");

outer.addEventListener("click", () => {
  console.log("Outer clicked");
});

inner.addEventListener("click", (e) => {
  e.stopPropagation();
  console.log("Inner clicked — stopped!");
});

// Click on .inner:
// → "Inner clicked — stopped!" (no bubbling to outer)

// ONE listener on the parent handles ALL items
document.querySelector("ul").addEventListener("click", (e) => {
  if (e.target.tagName === "LI") {
    console.log("Clicked: " + e.target.textContent);
    e.target.classList.toggle("selected");
  }
});

// Dynamically added items work automatically!
let newItem = document.createElement("li");
newItem.textContent = "New item";
document.querySelector("ul").appendChild(newItem);
// Clicking the new item triggers the same handler

// HTML: <div id="menu">
//   <button data-action="save">Save</button>
//   <button data-action="delete">Delete</button>
//   <button data-action="cancel">Cancel</button>
// </div>

document.querySelector("#menu").addEventListener("click", (e) => {
  let action = e.target.dataset.action;
  if (!action) return;

  switch (action) {
    case "save": console.log("Saving..."); break;
    case "delete": console.log("Deleting..."); break;
    case "cancel": console.log("Cancelling..."); break;
  }
});
